<?php require_once __DIR__.'/includes/permissions.php';require_permission('analytics.view');$pdo=db();$service=$pdo->query('SELECT s.name,COUNT(hr.id) total FROM services s LEFT JOIN health_records hr ON hr.service_id=s.id AND hr.status="Active" GROUP BY s.id ORDER BY total DESC')->fetchAll();$monthly=$pdo->query('SELECT DATE_FORMAT(record_date,"%Y-%m") ym,COUNT(*) total FROM health_records WHERE record_date>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) AND status="Active" GROUP BY ym ORDER BY ym')->fetchAll();$barangay=$pdo->query('SELECT barangay,COUNT(*) total FROM residents WHERE status="Active" GROUP BY barangay ORDER BY total DESC')->fetchAll();$vax=$pdo->query('SELECT vaccine,COUNT(*) total FROM vaccinations WHERE status="Active" GROUP BY vaccine ORDER BY total DESC')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>Analytics</h1><p>Database-driven operational analytics. Empty data produces zero counts.</p></div></div><div class="row g-4"><div class="col-lg-6"><div class="panel"><h5>Health Records by Service</h5><canvas id="c1"></canvas></div></div><div class="col-lg-6"><div class="panel"><h5>Monthly Health Record Activity</h5><canvas id="c2"></canvas></div></div><div class="col-lg-6"><div class="panel"><h5>Residents by Barangay</h5><canvas id="c3"></canvas></div></div><div class="col-lg-6"><div class="panel"><h5>Vaccinations by Vaccine</h5><canvas id="c4"></canvas></div></div></div><script>const mk=(id,type,labels,data,label)=>new Chart(document.getElementById(id),{type,data:{labels,datasets:[{label,data}]},options:{responsive:true,scales:type==='bar'?{y:{beginAtZero:true,ticks:{precision:0}}}:{}}});mk('c1','bar',<?=json_encode(array_column($service,'name'))?>,<?=json_encode(array_map('intval',array_column($service,'total')))?>,'Records');mk('c2','line',<?=json_encode(array_column($monthly,'ym'))?>,<?=json_encode(array_map('intval',array_column($monthly,'total')))?>,'Records');mk('c3','bar',<?=json_encode(array_column($barangay,'barangay'))?>,<?=json_encode(array_map('intval',array_column($barangay,'total')))?>,'Residents');mk('c4','bar',<?=json_encode(array_column($vax,'vaccine'))?>,<?=json_encode(array_map('intval',array_column($vax,'total')))?>,'Vaccinations');</script><?php include __DIR__.'/includes/footer.php'; ?>
